using System;using Game.Components;using Game.Skirmish.Contracts;using Unity.Entities;using Unity.Collections;
namespace Game.Runtime {
 internal sealed partial class AutonomousWorld {
  SkirmishRosterProjectionSystem sourceRoster;SystemState sourceRosterState;bool sourceRosterCreated,initialRosterStatsObserved;
  internal int ObservedRosterOverlayCount {get;private set;}internal int ObservedStructureAttackCount{get;private set;}
  void InitializeActualRosterOwner(){if(sourceRosterCreated)throw new InvalidOperationException("Original roster owner creates once");sourceRosterState=FreshState();sourceRosterState.Begin();sourceRoster.OnCreate(ref sourceRosterState);sourceRosterState.End();sourceRosterState.LastSystemVersion=0;sourceRosterCreated=true;InitializeActualVehicleWreckOwner();}
  void AdvanceActualRosterOwner(){if(!sourceRosterCreated)throw new InvalidOperationException("Original roster owner missing");sourceRosterState.Begin();if(sourceRosterState.Enabled&&sourceRosterState.RequiredQueriesPresent)sourceRoster.OnUpdate(ref sourceRosterState);sourceRosterState.End();ValidateActualRosterState();if(!initialRosterStatsObserved){ValidateActualInitialRosterStats();initialRosterStatsObserved=true;}}
  void ValidateActualInitialRosterStats(){foreach(var entity in OpeningActors){var overlay=Entities.GetComponentData<SkirmishRoleOverlayComponent>(entity);var health=Entities.GetComponentData<UnitHealth>(entity);if(health.Max!=overlay.MaxHealth||health.Current!=overlay.MaxHealth)throw new InvalidOperationException("Original initial role health was not observed");if(overlay.Damage>0&&Entities.HasComponent<UnitAttack>(entity)){var attack=Entities.GetComponentData<UnitAttack>(entity);if(attack.Damage!=overlay.Damage||attack.Range!=overlay.RangeWorld)throw new InvalidOperationException("Original initial role attack stats were not observed");}}}
  void ValidateActualRosterState(){int overlays=0,structureAttack=0;var id=Entities.GetComponentData<SkirmishExpandedSessionComponent>(Session).SessionId;using var q=Entities.CreateEntityQuery(typeof(SkirmishAttemptOwnedComponent),typeof(SkirmishUnitRoleComponent));using var rows=q.ToEntityArray(Allocator.Temp);foreach(var entity in rows){var owner=Entities.GetComponentData<SkirmishAttemptOwnedComponent>(entity);if(!owner.SessionId.Equals(id)||owner.IsStructure!=0)continue;if(!Entities.HasComponent<SkirmishRoleOverlayComponent>(entity)||!Entities.HasComponent<UnitHealth>(entity))throw new InvalidOperationException("Original roster did not publish actual role/health");var overlay=Entities.GetComponentData<SkirmishRoleOverlayComponent>(entity);if(overlay.Applied==0||overlay.Role!=Entities.GetComponentData<SkirmishUnitRoleComponent>(entity).Role)throw new InvalidOperationException("Actual source overlay absent/mismatched");var health=Entities.GetComponentData<UnitHealth>(entity);if(health.Max<=0||health.Current<=0&&!Entities.HasComponent<UnitDeathAnimationComponent>(entity)&&!Entities.HasComponent<VehicleWreckComponent>(entity))throw new InvalidOperationException("Source health lacks live/valid death state");if(health.Current>0&&overlay.Damage>0&&overlay.TargetDomains!=SkirmishTargetDomain.None){if(Entities.HasComponent<CampaignMissionCombatSuppressedTag>(entity))throw new InvalidOperationException("Original roster left active combatant suppressed");if(!Entities.HasComponent<UnitAttack>(entity)&&!Entities.HasComponent<GroundMissileLauncherComponent>(entity)&&!Entities.HasComponent<AirMissileLauncherComponent>(entity))throw new NotSupportedException("Actual source combat owner absent");}if(owner.FactionId==1&&overlay.Damage>0&&(overlay.TargetDomains&SkirmishTargetDomain.Structure)!=0&&SkirmishArmyGroupSystem.IsAlive(Entities,entity))structureAttack++;overlays++;}ObservedRosterOverlayCount=overlays;ObservedStructureAttackCount=structureAttack;}
 }
}
